{
  "story_id": "S10",
  "test_cases": [
    {
      "case_id": "TC01",
      "title": "Appeal a declined claim by replying to the decision letter",
      "technique": "positive",
      "covers": ["AC1", "AC2"],
      "preconditions": [
        "The member has a declined claim and its decision letter.",
        "The member can reply to the decision letter."
      ],
      "steps": [
        "Reply to the decision letter with an explanation of why the member thinks the decision is wrong."
      ],
      "expected_result": "The member can appeal the declined claim by replying to the decision letter, and the appeal states why the member thinks the decision is wrong."
    },
    {
      "case_id": "TC02",
      "title": "Appeal a declined claim through the member portal",
      "technique": "positive",
      "covers": ["AC1", "AC2"],
      "preconditions": [
        "The member has a declined claim.",
        "The member can access the member portal."
      ],
      "steps": [
        "Submit an appeal for the declined claim through the member portal, explaining why the member thinks the decision is wrong."
      ],
      "expected_result": "The member can appeal the declined claim through the member portal, and the appeal states why the member thinks the decision is wrong."
    },
    {
      "case_id": "TC03",
      "title": "Appeal with a reason and no additional missing information",
      "technique": "positive",
      "covers": ["AC2"],
      "preconditions": [
        "The member has a declined claim."
      ],
      "steps": [
        "Submit an appeal explaining why the member thinks the decision is wrong without including additional information missing from the original claim."
      ],
      "expected_result": "The appeal states why the member thinks the decision is wrong. The stated criteria allow additional information to be included but do not require it."
    },
    {
      "case_id": "TC04",
      "title": "Include examples of information missing from the original claim",
      "technique": "positive",
      "covers": ["AC2"],
      "preconditions": [
        "The member has a declined claim.",
        "The member has a referral, a pre-authorisation number, and a provider description showing the injury was accidental."
      ],
      "steps": [
        "Submit an appeal explaining why the member thinks the decision is wrong and include the referral, pre-authorisation number, and provider description."
      ],
      "expected_result": "The appeal states why the member thinks the decision is wrong and can include the referral, pre-authorisation number, and provider description showing the injury was accidental."
    },
    {
      "case_id": "TC05",
      "title": "Submit an appeal without stating why the decision is wrong",
      "technique": "negative",
      "covers": ["AC2"],
      "preconditions": [
        "The member has a declined claim."
      ],
      "steps": [
        "Submit an appeal without stating why the member thinks the decision is wrong."
      ],
      "expected_result": "The appeal contains no stated reason, so it does not meet AC2's requirement that an appeal state why the member thinks the decision is wrong. The criteria do not specify whether submission is blocked or what other handling occurs."
    },
    {
      "case_id": "TC06",
      "title": "Have the appeal reviewed by an independent senior claims assessor",
      "technique": "positive",
      "covers": ["AC3"],
      "preconditions": [
        "The claim was declined by an identified claims assessor.",
        "The appeal has reached review."
      ],
      "steps": [
        "Inspect who reviews the appeal, their role, and whether they were involved in the original decision."
      ],
      "expected_result": "The appeal is reviewed by a senior claims assessor who was not involved in the original decision."
    },
    {
      "case_id": "TC07",
      "title": "Do not have the original decision-maker review the appeal",
      "technique": "negative",
      "covers": ["AC3"],
      "preconditions": [
        "The claim was declined by an identified claims assessor.",
        "The appeal has reached review."
      ],
      "steps": [
        "Inspect whether the assessor who made the original decision reviews the appeal."
      ],
      "expected_result": "The original decision-maker is not the appeal reviewer; the appeal is reviewed by a senior claims assessor who was not involved in the original decision."
    },
    {
      "case_id": "TC08",
      "title": "Ensure the appeal reviewer is senior",
      "technique": "negative",
      "covers": ["AC3"],
      "preconditions": [
        "The claim was declined by an identified claims assessor.",
        "The appeal has reached review."
      ],
      "steps": [
        "Inspect the role of the assessor reviewing the appeal."
      ],
      "expected_result": "The appeal reviewer is a senior claims assessor and was not involved in the original decision."
    },
    {
      "case_id": "TC09",
      "title": "Handle dissatisfaction with service as a complaint",
      "technique": "negative",
      "covers": ["AC4"],
      "preconditions": [
        "The member is dissatisfied with the service.",
        "The member is not expressing dissatisfaction with a claim decision."
      ],
      "steps": [
        "Submit the member's service dissatisfaction for handling."
      ],
      "expected_result": "The service dissatisfaction is handled as a complaint, not as an appeal."
    }
  ]
}
